changeSet.sql:
ALTER TABLE hive_edr_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE hive_edr_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON hive_edr_event
    USING (tenant_id = COALESCE(NULLIF(current_setting('app.current_tenant', true), '')::bigint, -1))
    WITH CHECK (tenant_id = COALESCE(NULLIF(current_setting('app.current_tenant', true), '')::bigint, -1));

changeSet.rollback:
DROP POLICY IF EXISTS tenant_isolation ON hive_edr_event;
ALTER TABLE hive_edr_event NO FORCE ROW LEVEL SECURITY;
ALTER TABLE hive_edr_event DISABLE ROW LEVEL SECURITY;

